# -*- coding: utf-8 -*-
# Рядок 404 (РОЗБІР-404): ЗВІДКИ вигадки MamayLM на еталоні 60 речей і що дав би «перезапуск». Друкує факт, без моделі.
# (1) поле × п/х/в (правильно/хибно/вигадано), група, перелік вигадок; (2) значення-заповнювачі; (3) які поля позначені для перезапуску і чим
# заповнити пробіл продукту (б — продукт сьогодні, з еталона; г — розбір); (4) з 2+ файлами — узгодженість: значення лишається, коли його дали ≥2.
# Запуск: python3 -I джерела/проби/розбір_вигадки_404.py розбір.json [розбір_2.json розбір_3.json]   (~1 с; каталогу й моделі не треба)
import sys, ast, os, json, collections as C
Т = os.path.dirname(os.path.abspath(__file__)); Е = json.load(open(Т + '/еталон_розбору.json', encoding='utf-8')); ПОЛЯ = Е['поля']
д = ast.parse(open(Т + '/еталон_частки.py', encoding='utf-8').read()); exec(compile(ast.Module([в for в in д.body if isinstance(в, ast.FunctionDef)], []), 'x', 'exec'))
РЗ = [json.load(open(ф, encoding='utf-8')) for ф in sys.argv[1:]]; МАПА = ('item_type', 'cut', 'fabric', 'length', 'sleeve', 'pattern'); ПР = {'правильно': 'п', 'хибно': 'х', 'вигадано': 'в'}
пусто = lambda v: v in (None, 'unknown', [], 'нема поля'); ключ = lambda v: json.dumps(v, sort_keys=True)
коди = lambda р, к: з_розбору(к[р['id']], 'shoes' in р['правда']['slot'])
def голос(р, п):   # значення, яке дали ≥2 прогони (інакше None)
    с = C.Counter(ключ(коди(р, к)[п]) for к in РЗ if р['id'] in к and not пусто(коди(р, к)[п])); return json.loads(с.most_common(1)[0][0]) if с and с.most_common(1)[0][1] >= 2 else None
def підсумок(назва, вибір, поля=ПОЛЯ):   # вибір(р, п, г, б, опора) → True: взяти г, інакше лишається продукт (б)
    с = C.Counter()
    for р in Е['речі']:
        г = коди(р, РЗ[0])
        for п in поля: оп = р['опора'].get(п, []); взяти = not пусто(г[п]) and вибір(р, п, г[п], р['джерела']['б'][п], оп); с[ПР.get(суд(р['правда'][п], оп, г[п], True) if взяти else р['вердикти']['б'][п], 'м')] += 1
    print('  %-44s правильно %3d · хибно %3d · вигадано %3d · мовчання %3d' % (назва, с['п'], с['х'], с['в'], с['м']))
пол, гр, зн, речі_в, виг, поз, речі_п = *[C.defaultdict(C.Counter) for _ in range(3)], C.Counter(), [], C.Counter(), set()
for р in Е['речі']:
    г = коди(р, РЗ[0])
    for п in ПОЛЯ:
        if пусто(г[п]): continue
        в = ПР.get(суд(р['правда'][п], р['опора'].get(п, []), г[п], True), 'м'); пол[п][в] += 1; гр[р['група']][в] += 1; гр['#' + р['правда']['slot'][0]][в] += 1; зн[п, str(г[п])][в] += 1; речі_в[р['id']] += в == 'в'
        if в == 'в': виг.append('%s:%s=%s' % (р['id'].split('@')[0], п, г[п]))
        позн = пусто(р['джерела']['б'][п]) or р['джерела']['б'][п] != г[п]; поз[в, позн] += 1; речі_п |= {р['id']} if позн else set()
print('(1) поставлено г %d: правильно %d · хибно %d · вигадано %d · речей з вигадкою %d з 60 · поле п/х/в: ' % (sum(map(sum, [v.values() for v in пол.values()])), *(sum(v[к] for v in пол.values()) for к in 'пхв'), sum(1 for v in речі_в.values() if v)) + ' · '.join('%s %d/%d/%d' % (п, *(пол[п][к] for к in 'пхв')) for п in sorted(пол, key=lambda п: -пол[п]['в'])))
print('    за групою/слотом: ' + ' · '.join('%s %d/%d/%d' % (к, *(v[x] for x in 'пхв')) for к, v in sorted(гр.items())) + '\n    вигадки: ' + ' '.join(виг))
print('(2) значення, що частіше хибні, ніж правильні (п/х/в): ' + ' · '.join('%s=%s %d/%d/%d' % (*к, *(v[x] for x in 'пхв')) for к, v in sorted(зн.items(), key=lambda t: -t[1]['в']) if v['п'] < v['х'] + v['в'] and v['х'] + v['в'] > 1))
усе = lambda к: sum(v for (в, _), v in поз.items() if в == к)
print('(3) поля, де продукт мовчить або суперечить розбору (кандидати на перезапуск): %d з %d кодів — вигадок %d з %d, хибних %d з %d, правильних %d з %d; речей з таким полем %d з 60' % (
    sum(v for (_, п), v in поз.items() if п), sum(поз.values()), поз['в', True], усе('в'), поз['х', True], усе('х'), поз['п', True], усе('п'), len(речі_п)))
print('    6 полів заміни продуктом→розбором (_ЗАМІНЕНІ_РОЗБОРОМ):'); Правила = [('лише продукт (б)', lambda *а: False), ('заміна завжди (план)', lambda *а: True), ('лише де продукт мовчить', lambda р, п, г, б, о: пусто(б)),
    ('де мовчить, лише рукав+візерунок', lambda р, п, г, б, о: пусто(б) and п in ('sleeve', 'pattern')), ('де мовчить і є опора в тексті (оракул цитат)', lambda р, п, г, б, о: пусто(б) and bool(о))]
for н, ф in Правила: підсумок(н, ф, МАПА)
if len(РЗ) > 1: print('(4) %d прогони: поля, де вони не збіглися, %d з %d' % (len(РЗ), sum(len({ключ(коди(р, к)[п]) for к in РЗ if р['id'] in к}) > 1 for р in Е['речі'] for п in ПОЛЯ), 60 * len(ПОЛЯ))); підсумок('значення лише коли ≥2 прогони згодні', lambda р, п, г, б, о: голос(р, п) is not None and голос(р, п) == г, ПОЛЯ); підсумок('перший прогін як є (усі 12 полів)', lambda *а: True, ПОЛЯ)
